"use client";

import { useTranslations, useLocale } from "next-intl";
import { useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { searchProducts, Product } from "@/lib/api";
import { useBasket } from "@/lib/basket-store";
import { Input } from "@/components/ui/input";
import ProductCard from "@/components/search/ProductCard";

export default function SearchBar() {
  const t = useTranslations("hero");
  const tCommon = useTranslations("common");
  const locale = useLocale();
  const router = useRouter();
  const { addItem } = useBasket();

  const [query, setQuery] = useState("");
  const [results, setResults] = useState<Product[]>([]);
  const [loading, setLoading] = useState(false);
  const [focused, setFocused] = useState(false);
  const debounceRef = useRef<ReturnType<typeof setTimeout>>(null);

  const handleSearch = (q: string) => {
    setQuery(q);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    if (!q.trim()) { setResults([]); return; }
    debounceRef.current = setTimeout(async () => {
      setLoading(true);
      setResults(await searchProducts(q));
      setLoading(false);
    }, 300);
  };

  return (
    <div className="relative">
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <Input
            type="text"
            value={query}
            onChange={(e) => handleSearch(e.target.value)}
            onFocus={() => setFocused(true)}
            onBlur={() => setTimeout(() => setFocused(false), 200)}
            placeholder={t("searchPlaceholder")}
            dir="auto"
          />
          {loading && (
            <div className="absolute end-4 top-1/2 -translate-y-1/2">
              <div className="w-4 h-4 border-2 border-walnut-400 border-t-transparent rounded-full animate-spin" />
            </div>
          )}
        </div>

        {/* Barcode scanner */}
        <button
          className="flex items-center justify-center w-[54px] h-[54px] bg-stone-100 hover:bg-stone-200 rounded-2xl transition-colors group flex-shrink-0"
          title={t("scanBarcode")}
          onClick={() => alert("Barcode scanner — coming soon!")}
        >
          <svg className="w-5 h-5 text-stone-500 group-hover:text-stone-800 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5}
              d="M3 4h2v16H3V4zm3 0h1v16H6V4zm2 0h2v16H8V4zm3 0h1v16h-1V4zm2 0h2v16h-2V4zm3 0h1v16h-1V4zm2 0h2v16h-2V4z" />
          </svg>
        </button>
      </div>

      {/* Dropdown results */}
      <AnimatePresence>
        {focused && results.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 4, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 4, scale: 0.98 }}
            transition={{ duration: 0.15 }}
            className="absolute top-full start-0 end-0 mt-2 bg-white rounded-2xl shadow-[0_8px_32px_-4px_rgba(0,0,0,0.12)] border border-stone-200 overflow-hidden z-50 max-h-96 overflow-y-auto"
          >
            {results.map((product) => (
              <ProductCard
                key={product.barcode}
                product={product}
                onAdd={() => addItem({ barcode: product.barcode, name: product.name, brand: product.brand, imageUrl: product.image_url })}
                onClick={() => router.push(`/${locale}/product/${product.barcode}`)}
              />
            ))}
          </motion.div>
        )}

        {focused && query && !loading && results.length === 0 && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute top-full start-0 end-0 mt-2 bg-white rounded-2xl shadow-[0_8px_32px_-4px_rgba(0,0,0,0.12)] border border-stone-200 p-6 text-center text-stone-400 z-50"
          >
            {tCommon("notFound")}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
