"use client";

import { useTranslations, useLocale } from "next-intl";
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useBasket } from "@/lib/basket-store";
import { compareBasket, BasketCompareResponse, searchProducts, Product } from "@/lib/api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import BasketResults from "./BasketResults";

export default function BasketBuilder() {
  const t = useTranslations("basket");
  const tHero = useTranslations("hero");
  const tCommon = useTranslations("common");
  const { items, addItem, removeItem, updateQuantity, clearBasket } = useBasket();

  const [query, setQuery] = useState("");
  const [suggestions, setSuggestions] = useState<Product[]>([]);
  const [comparing, setComparing] = useState(false);
  const [results, setResults] = useState<BasketCompareResponse | null>(null);
  const [debounce, setDebounce] = useState<ReturnType<typeof setTimeout>>();

  const handleSearch = (q: string) => {
    setQuery(q);
    if (debounce) clearTimeout(debounce);
    if (!q.trim()) { setSuggestions([]); return; }
    setDebounce(setTimeout(async () => {
      setSuggestions(await searchProducts(q, 6));
    }, 300));
  };

  const handleCompare = async () => {
    if (!items.length) return;
    setComparing(true);
    setResults(null);
    const res = await compareBasket(items.map((i) => ({ barcode: i.barcode, quantity: i.quantity })));
    setResults(res);
    setComparing(false);
  };

  return (
    <div className="space-y-4">
      {/* Search input */}
      <div className="relative">
        <Input
          type="text"
          value={query}
          onChange={(e) => handleSearch(e.target.value)}
          placeholder={tHero("basketPlaceholder")}
          dir="auto"
        />

        {/* Autocomplete dropdown */}
        <AnimatePresence>
          {suggestions.length > 0 && query && (
            <motion.div
              initial={{ opacity: 0, y: 4, scale: 0.98 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 4, scale: 0.98 }}
              transition={{ duration: 0.15 }}
              className="absolute top-full start-0 end-0 mt-2 bg-white rounded-2xl shadow-[0_8px_32px_-4px_rgba(0,0,0,0.12)] border border-stone-200 overflow-hidden z-50"
            >
              {suggestions.map((p) => (
                <motion.div
                  key={p.barcode}
                  onClick={() => {
                    addItem({ barcode: p.barcode, name: p.name, brand: p.brand, imageUrl: p.image_url });
                    setQuery("");
                    setSuggestions([]);
                  }}
                  whileHover={{ backgroundColor: "rgb(245,245,245)" }}
                  className="flex items-center gap-3 px-4 py-3 cursor-pointer border-b border-stone-100 last:border-0"
                >
                  <div className="w-8 h-8 rounded-xl bg-stone-100 flex items-center justify-center text-base flex-shrink-0">📦</div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-semibold text-stone-900 truncate">{p.name}</p>
                    {p.brand && <p className="text-xs text-stone-400">{p.brand}</p>}
                  </div>
                  <span className="text-xs text-walnut-400 font-medium flex-shrink-0">הוסף +</span>
                </motion.div>
              ))}
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Basket items list */}
      <AnimatePresence initial={false}>
        {items.length > 0 ? (
          <motion.div
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            className="rounded-2xl border border-stone-200 overflow-hidden"
          >
            {/* Header row */}
            <div className="flex items-center justify-between px-4 py-2.5 bg-stone-50 border-b border-stone-100">
              <span className="text-xs font-semibold text-stone-500 uppercase tracking-wider">
                {items.length} {t("items")}
              </span>
              <button
                onClick={clearBasket}
                className="text-xs text-stone-400 hover:text-stone-700 font-medium transition-colors"
              >
                {t("clear")}
              </button>
            </div>

            {/* Item rows */}
            <div className="max-h-44 overflow-y-auto divide-y divide-stone-100">
              <AnimatePresence>
                {items.map((item) => (
                  <motion.div
                    key={item.barcode}
                    initial={{ opacity: 0, x: -8 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 8 }}
                    transition={{ duration: 0.18 }}
                    className="flex items-center gap-3 px-4 py-2.5"
                  >
                    <span className="flex-1 text-sm text-stone-800 font-medium truncate">{item.name}</span>
                    <div className="flex items-center gap-1 flex-shrink-0">
                      <button
                        onClick={() => updateQuantity(item.barcode, item.quantity - 1)}
                        className="w-7 h-7 rounded-lg bg-stone-100 hover:bg-stone-200 text-stone-700 text-sm font-bold transition-colors flex items-center justify-center"
                      >−</button>
                      <span className="text-sm text-stone-800 w-6 text-center font-semibold tabular-nums">{item.quantity}</span>
                      <button
                        onClick={() => updateQuantity(item.barcode, item.quantity + 1)}
                        className="w-7 h-7 rounded-lg bg-stone-100 hover:bg-stone-200 text-stone-700 text-sm font-bold transition-colors flex items-center justify-center"
                      >+</button>
                      <button
                        onClick={() => removeItem(item.barcode)}
                        className="w-7 h-7 rounded-lg hover:bg-red-50 text-stone-300 hover:text-red-400 transition-colors flex items-center justify-center ms-1"
                      >
                        <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                          <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                        </svg>
                      </button>
                    </div>
                  </motion.div>
                ))}
              </AnimatePresence>
            </div>

            {/* Compare CTA */}
            <div className="px-4 py-3.5 bg-stone-50 border-t border-stone-100">
              <Button
                onClick={handleCompare}
                disabled={comparing}
                className="w-full"
                size="lg"
              >
                {comparing ? (
                  <>
                    <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    {tCommon("loading")}
                  </>
                ) : (
                  `🔍 ${t("compareAll")}`
                )}
              </Button>
            </div>
          </motion.div>
        ) : (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-center py-8 text-stone-400 text-sm"
          >
            {t("empty")}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Results */}
      <AnimatePresence>
        {results && (
          <motion.div
            initial={{ opacity: 0, y: 12 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.3, ease: [0.22, 1, 0.36, 1] }}
          >
            <BasketResults results={results} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
