"use client";

import { useTranslations, useLocale } from "next-intl";
import { motion } from "framer-motion";
import { BasketCompareResponse } from "@/lib/api";

interface Props {
  results: BasketCompareResponse;
}

export default function BasketResults({ results }: Props) {
  const t = useTranslations("basket");
  const tCommon = useTranslations("common");
  const locale = useLocale();

  const cheapest = results.stores[0];
  const maxSavings = Number(results.max_savings);

  return (
    <div className="space-y-2">
      {/* Savings banner */}
      {maxSavings > 0 && (
        <motion.div
          initial={{ opacity: 0, scale: 0.96 }}
          animate={{ opacity: 1, scale: 1 }}
          className="bg-green-50 border border-green-200 rounded-2xl px-4 py-3 text-center"
        >
          <span className="text-green-700 font-semibold text-sm">
            💰 {locale === "he"
              ? `חיסכון אפשרי של ${tCommon("nis")}${maxSavings.toFixed(2)}`
              : `Potential savings of ${tCommon("nis")}${maxSavings.toFixed(2)}`}
          </span>
        </motion.div>
      )}

      <div className="max-h-80 overflow-y-auto space-y-2 pr-0.5">
        {results.stores.map((store, i) => {
          const isCheapest = i === 0;
          const savingsVsCheapest = Number(store.total_price) - Number(cheapest.total_price);

          return (
            <motion.div
              key={store.store.id}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05, duration: 0.25 }}
              className={`rounded-2xl border transition-all ${
                isCheapest
                  ? "bg-walnut-50 border-walnut-200"
                  : "bg-white border-stone-200"
              }`}
            >
              <div className="flex items-center gap-3 px-4 py-3">
                {/* Rank badge */}
                <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold flex-shrink-0 ${
                  isCheapest
                    ? "bg-walnut-500 text-white"
                    : "bg-stone-100 text-stone-500"
                }`}>
                  {i + 1}
                </div>

                {/* Store info */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="text-sm font-semibold text-stone-900 truncate">
                      {store.store.chain.name}
                    </span>
                    {isCheapest && (
                      <span className="text-xs px-2 py-0.5 rounded-full bg-walnut-100 text-walnut-700 font-medium flex-shrink-0">
                        {t("cheapestStore")}
                      </span>
                    )}
                  </div>
                  <div className="flex items-center gap-2 text-xs text-stone-400 mt-0.5 flex-wrap">
                    {store.store.name && <span className="truncate">{store.store.name}</span>}
                    {store.store.city && <span>· {store.store.city}</span>}
                    {store.items_missing > 0 && (
                      <span className="text-orange-500">· {store.items_missing} {t("missing")}</span>
                    )}
                  </div>
                </div>

                {/* Price */}
                <div className="text-end flex-shrink-0">
                  <div className={`text-lg font-bold tabular-nums ${isCheapest ? "text-walnut-700" : "text-stone-800"}`}>
                    {tCommon("nis")}{Number(store.total_price).toFixed(2)}
                  </div>
                  {savingsVsCheapest > 0.01 && (
                    <div className="text-xs text-orange-500 font-medium">
                      +{tCommon("nis")}{savingsVsCheapest.toFixed(2)}
                    </div>
                  )}
                </div>
              </div>

              {/* Transfer basket CTA — cheapest only */}
              {isCheapest && (
                <div className="px-4 pb-3.5">
                  <button
                    className="w-full py-2.5 rounded-xl bg-walnut-500 hover:bg-walnut-600 active:scale-[0.99] text-white text-xs font-bold transition-all duration-150 shadow-sm"
                    onClick={() => alert(`Transfer basket to ${store.store.chain.name} — coming soon!`)}
                  >
                    🚀 {t("transferBasket")} · {store.store.chain.name}
                  </button>
                </div>
              )}
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}
