import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { forwardRef } from "react";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 font-bold tracking-wide transition-all duration-200 cursor-pointer select-none disabled:opacity-40 disabled:cursor-not-allowed active:scale-[0.97]",
  {
    variants: {
      variant: {
        primary:   "bg-lime-400 text-ink-900 hover:bg-lime-300 shadow-lime-glow hover:shadow-[0_0_48px_0_rgba(204,255,0,0.3)] rounded-full",
        secondary: "bg-ink-600 text-editorial-white hover:bg-ink-500 border border-ink-500 rounded-full",
        ghost:     "text-editorial-muted hover:text-editorial-white hover:bg-ink-700 rounded-xl",
        outline:   "border border-ink-500 text-editorial-muted hover:border-lime-400 hover:text-lime-400 rounded-full",
      },
      size: {
        sm: "text-xs px-4 py-2 h-9",
        md: "text-sm px-5 py-2.5 h-10",
        lg: "text-sm px-7 py-3.5 h-12",
      },
    },
    defaultVariants: { variant: "primary", size: "md" },
  }
);

interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {}

const Button = forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, ...props }, ref) => (
    <button ref={ref} className={cn(buttonVariants({ variant, size }), className)} {...props} />
  )
);
Button.displayName = "Button";

export { Button, buttonVariants };
