import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center gap-1.5 font-bold tracking-wider uppercase text-[10px] rounded-full px-3 py-1",
  {
    variants: {
      variant: {
        default: "bg-ink-600 text-editorial-muted border border-ink-500",
        lime:    "bg-lime-400 text-ink-900",
        outline: "border border-lime-400/40 text-lime-400",
        live:    "bg-ink-700 border border-ink-500 text-editorial-muted before:w-1.5 before:h-1.5 before:rounded-full before:bg-lime-400 before:inline-block before:animate-pulse",
      },
    },
    defaultVariants: { variant: "default" },
  }
);

interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <span className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };
